class AppNotification {
  final String id;
  final String? type;
  final String title;
  final String body;
  final bool isRead;
  final DateTime createdAt;
  final Map<String, dynamic>? payload;

  AppNotification({
    required this.id,
    this.type,
    required this.title,
    required this.body,
    required this.isRead,
    required this.createdAt,
    this.payload,
  });

  factory AppNotification.fromJson(Map<String, dynamic> json) {
    final payload = json['payload'] is Map<String, dynamic>
        ? json['payload'] as Map<String, dynamic>
        : null;

    return AppNotification(
      id: json['id']?.toString() ?? '',
      type: json['type']?.toString(),
      title: json['title']?.toString() ?? (payload != null ? payload['title']?.toString() : '') ?? '',
      body: json['body']?.toString() ?? (payload != null ? payload['body']?.toString() : '') ?? '',
      isRead: json['is_read'] == true || json['is_read']?.toString() == '1',
      createdAt: DateTime.tryParse(json['created_at']?.toString() ?? '') ?? DateTime.now(),
      payload: payload,
    );
  }
}
